function profileTemplates(){const items=list(ui.draft.templates);return collectionHeading('Progress message templates','templates')+`<p class="muted">Preview the actual subject and body against original source facts before releasing the configuration. Each template has an explicit audience and source-backed stage.</p><details><summary>Available placeholders and stage facts</summary><pre id="placeholder-help">${esc(pretty(templateContract))}</pre></details>`+items.map((t,i)=>{const p='templates.'+i;return `<section class="panel">${itemHeading(t.name||'New template','templates',i,items.length)}<div class="form-grid">${field(p+'.name','Template name',{required:true})}${field(p+'.id','Template reference',{required:true})}${field(p+'.audience','Audience',{values:['staff','resident']})}${field(p+'.stage','Progress stage',{values:['received','assigned','in_progress','resolved','closed_other']})}${field(p+'.locale','Language tag',{placeholder:'en-US'})}${field(p+'.active','Active',{type:'checkbox'})}</div>${field(p+'.subject','Subject',{required:true})}${field(p+'.body','Message body',{type:'textarea',rows:7,required:true})}<details class="subpanel"><summary>Resident wording for staff and work details</summary><p class="hint">Supply wording intended for residents when a resident message uses these placeholders. Blank values remain unresolved in the resident preview.</p><div class="form-grid">${field(p+'.residentWording.assignee_name','Resident-facing responsibility',{kind:'optional-text',help:'Text used by {{assignee_name}} in resident messages.'})}${field(p+'.residentWording.completion_note','Resident completion wording',{type:'textarea',kind:'optional-text',rows:4,help:'Text used by {{completion_note}} in resident messages.'})}${field(p+'.residentWording.progress_summary','Resident progress wording',{type:'textarea',kind:'optional-text',rows:4,help:'Text used by {{progress_summary}} in resident messages.'})}</div></details></section>`;}).join('');}
function profileRoutes(){const items=list(ui.draft.routes);return collectionHeading('Responsibility routing','routes')+`<p class="muted">A route can narrow the category by original source fields. The preview shows all matches and requires an explicit resolution when more than one route applies.</p>`+items.map((r,i)=>{const p='routes.'+i;return `<section class="panel">${itemHeading(r.name||'New route','routes',i,items.length)}<div class="form-grid">${field(p+'.name','Route name',{required:true})}${field(p+'.id','Route reference',{required:true})}${field(p+'.active','Active',{type:'checkbox'})}${field(p+'.categoryIds','Categories',{type:'multiple',values:list(ui.draft.categories)})}${field(p+'.sourceProfileIds','Source profiles',{type:'multiple',values:list(ui.draft.sourceProfiles)})}${field(p+'.departmentId','Responsible department',{values:list(ui.draft.departments),empty:'Keep category department'})}${field(p+'.ownerStaffId','Responsible staff member',{values:list(ui.draft.staff),empty:'Keep category owner'})}${field(p+'.collaboratorStaffIds','Collaborators',{type:'multiple',values:list(ui.draft.staff)})}${field(p+'.templateIds','Progress templates',{type:'multiple',values:list(ui.draft.templates)})}</div><h3>Original source conditions</h3>${nestedItems(p+'.selectors','route selector',(_,j,k)=>`<div class="form-grid">${field(k+'.field','Semantic field',{values:[...semanticFields,...list(ui.draft.categories).flatMap(c=>list(c.customFields).map(f=>({id:'custom:'+f.id,name:c.name+' · '+(f.label||f.id)+' ('+f.scope+')'})))],required:true})}${field(k+'.operator','Comparison',{values:['equals','in']})}${field(k+'.value','Exact value',{type:'textarea',kind:'json',rows:2,help:'Used by equals.'})}${field(k+'.values','Allowed values',{type:'textarea',kind:'json',rows:3,help:'JSON array used by in.'})}</div>`)}${field(p+'.note','Routing instructions',{type:'textarea',rows:3})}</section>`;}).join('');}
function sourceMapping(profileIndex){const sourceProfile=ui.draft.sourceProfiles[profileIndex],mapping=sourceProfile.mapping??{};const fields=[...new Set([...semanticFields,...Object.keys(mapping)])];return table(['Semantic field','Value source','Original JSON pointer or literal'],fields.map(name=>{const m=mapping[name],kind=m&&Object.prototype.hasOwnProperty.call(m,'literal')?'literal':m?.pointer!==undefined?'pointer':'unused',value=ui.rawDrafts['sourceProfiles.'+profileIndex+'.mapping.'+name]??(kind==='literal'?pretty(m.literal):m?.pointer??'');return [`<label for="mapping-${profileIndex}-${esc(name)}">${esc(name)}</label>`,`<select data-map-kind="${esc(name)}" data-profile-index="${profileIndex}" aria-label="${esc(name)} value source">${options(['unused','pointer','literal'],kind)}</select>`,`<input id="mapping-${profileIndex}-${esc(name)}" data-map-value="${esc(name)}" data-profile-index="${profileIndex}" value="${esc(value)}" placeholder="${kind==='literal'?'JSON value':'/original/field_name'}"${kind==='unused'?' disabled':''}>`];}));}
function profileSources(){const items=list(ui.draft.sourceProfiles);return collectionHeading('Original source mappings','sourceProfiles')+`<p class="muted">Declare the exact array and row-relative JSON pointers used by each source. Inspect a retained file in Sources to copy its actual structure.</p>`+items.map((s,i)=>{const p='sourceProfiles.'+i;return `<section class="panel">${itemHeading(s.name||'New source profile','sourceProfiles',i,items.length)}<div class="form-grid">${field(p+'.name','Source profile name',{required:true})}${field(p+'.id','Source profile reference',{required:true})}${field(p+'.kind','Source format',{values:['open311_georeport_v2','follow_through_dispatch_v1','field_destination_update_v1','mapped_records']})}${field(p+'.rowsPointer','Original row array pointer',{help:'An empty pointer selects a root JSON array. Use /rows for an object containing a rows array.'})}</div><h3>Field mapping</h3>${sourceMapping(i)}<h3>Original status meanings</h3>${nestedItems(p+'.statusMappings','status mapping',(_,j,k)=>`<div class="form-grid">${field(k+'.sourceValue','Exact original status',{type:'textarea',kind:'json',rows:2})}${field(k+'.stage','Progress stage',{values:['received','assigned','in_progress','resolved','closed_other']})}${field(k+'.completionMeaning','Meaning of this status',{type:'textarea',rows:3,help:'Keep original dispositions distinct. A citation or administrative closure does not establish that physical work was completed.'})}</div>`)}${field(p+'.publicMapOverrideMapping','Original map-visibility mapping',{type:'textarea',kind:'json',rows:4,help:'Optional {"values":[{"sourceValue":"PUBLIC","publicMap":"show"}]}. Values may select show, hide or default. Input comes from the declared publicMapOverride field. Leave null when absent.'})}${field(p+'.note','Source mapping notes',{type:'textarea',rows:3})}</section>`;}).join('');}
function profileRollout(){const items=list(ui.draft.rollout);return collectionHeading('Training and rollout','rollout')+`<p class="muted">Prepare each audience with named ownership, intake and closure procedures, and explicit entry and exit criteria.</p>`+items.map((r,i)=>{const p='rollout.'+i;return `<section class="panel">${itemHeading(r.name||'New rollout phase','rollout',i,items.length)}<div class="form-grid">${field(p+'.name','Phase name',{required:true})}${field(p+'.id','Phase reference',{required:true})}${field(p+'.audience','Audience',{values:['staff','commissioners','resident']})}${field(p+'.ownerStaffId','Phase owner',{values:list(ui.draft.staff),empty:'Unassigned'})}${field(p+'.categoryIds','Categories',{type:'multiple',values:list(ui.draft.categories)})}${field(p+'.departmentIds','Departments',{type:'multiple',values:list(ui.draft.departments)})}</div><div class="form-grid two">${field(p+'.trainingItems','Training and operating procedures',{type:'textarea',kind:'lines',rows:7,help:'One actionable training or SOP item per line.'})}${field(p+'.entryCriteria','Entry criteria',{type:'textarea',kind:'lines',rows:5})}${field(p+'.exitCriteria','Exit criteria',{type:'textarea',kind:'lines',rows:5})}${field(p+'.note','Phase notes',{type:'textarea',rows:5})}</div></section>`;}).join('');}
async function renderProfiles(){if(!ui.draft)return pageHeading('Service configurations','Save the complete agency configuration, compare previews and issue an editable implementation handover.',button('New configuration','new-profile','',true)+button('Import definition','import-profile'))+table(['Configuration','Version','Saved',''],list(workspace.profiles).map(p=>[esc(p.name??p.definition?.name??p.id),`<code>${esc(short(p.versionId))}</code>`,esc(stamp(p.createdAt)),button('Open configuration','open-profile',`data-id="${esc(p.id)}"`)]));const renders={agency:profileAgency,categories:profileCategories,departments:profileDepartments,roles:()=>profilePermissions('roles'),groups:()=>profilePermissions('groups'),staff:profileStaff,templates:profileTemplates,routes:profileRoutes,sourceProfiles:profileSources,rollout:profileRollout};return pageHeading(ui.draft.name||'New service configuration','Save complete profile versions. Working edits remain available when moving between sections.',button('All configurations','close-profile')+button('Download working definition','download-draft')+(ui.profileId?downloadLink('Saved profile JSON','profile',{profileId:ui.profileId}):'')+button('Save profile version','save-profile','',true))+`<div class="configuration-summary"><span>Version ${esc(ui.baseVersion?short(ui.baseVersion):'new')}</span><span id="draft-status">Working draft saved in this browser.</span></div>${ui.staleDraft?`<section class="panel"><h2>A newer saved profile is available</h2><p>This draft began at an earlier profile version. Download it for comparison or reopen the current saved profile before saving.</p><div class="actions">${button('Download earlier draft','download-draft')}${button('Show saved version','show-saved-profile')}${button('Load current profile','load-current-profile')}${button('Save as a new configuration','fork-profile')}</div></section>`:''}<nav class="tabs" aria-label="Configuration sections">${sections.map(s=>`<button type="button" data-action="profile-section" data-section="${s}" aria-current="${ui.section===s?'page':'false'}">${esc(({agency:'Agency',categories:'Categories',departments:'Departments',roles:'Roles',groups:'Groups',staff:'Staff',templates:'Messages',routes:'Routing',sourceProfiles:'Source mappings',rollout:'Rollout'})[s])}</button>`).join('')}</nav><form id="profile-form"><div class="profile-section">${renders[ui.section]()}</div></form>${detail?.history?.length?`<details class="panel"><summary>Saved version history (${count(detail.history.length)})</summary>${table(['Version','Saved',''],detail.history.map(p=>[`<code>${esc(short(p.versionId))}</code>`,esc(stamp(p.createdAt)),button('View full definition','profile-version',`data-version="${esc(p.versionId)}"`)]))}</details>`:''}`;}
function newItem(kind){switch(kind){case'departments':return{id:uid('department'),name:'',active:true};case'staff':return{id:uid('staff'),name:'',departmentIds:[],roleId:'',groupIds:[],contact:'',active:true};case'roles':case'groups':return{id:uid(kind==='roles'?'role':'group'),name:'',description:'',active:true,permissions:{crmEnabled:false,crmProductAdmin:false,crmAccess:'none'},sourceLabel:'',sourceReference:''};case'categories':return{id:uid('category'),sourceSelectors:[],name:'',description:'',active:true,isOther:false,displayOrder:list(ui.draft.categories).length,includeLocation:false,locationRequired:false,departmentId:null,ownerStaffId:null,keywords:[],resolutionDays:null,publicMapDefault:'hide',customFields:[],templateIds:[]};case'templates':return{id:uid('template'),name:'',audience:'staff',stage:'received',subject:'',body:'',locale:'',active:true};case'routes':return{id:uid('route'),name:'',active:true,categoryIds:[],sourceProfileIds:[],selectors:[],departmentId:null,ownerStaffId:null,collaboratorStaffIds:[],templateIds:[],note:''};case'sourceProfiles':return{id:uid('source-profile'),name:'',kind:'mapped_records',rowsPointer:'',mapping:{},statusMappings:[],publicMapOverrideMapping:null,note:''};case'rollout':return{id:uid('phase'),name:'',audience:'staff',categoryIds:[],departmentIds:[],ownerStaffId:null,trainingItems:[],entryCriteria:[],exitCriteria:[],note:''};case'category selector':return{sourceProfileId:'',field:'serviceCode',value:''};case'custom field':return{id:uid('field'),label:'',kind:'text',scope:'submission',required:false,options:[],helpText:'',sourcePointer:''};case'field choice':return{value:'',label:''};case'route selector':return{field:'serviceCode',operator:'equals',value:'',values:[]};case'status mapping':return{sourceValue:'',stage:'received',completionMeaning:''};default:throw new Error('Unknown configuration item.');}}

function deployedBaselinePanel(){const versions=list(ui.baselineVersions).map(v=>({id:v.versionId,name:short(v.versionId)+' · '+stamp(v.createdAt)}));return `<details class="panel"${ui.baselineProfileId?' open':''}><summary>Known deployed configuration${ui.baselineProfileId?' · selected':''}</summary><p>Choose the exact saved version currently used by the agency to prepare permission and membership migration. An externally supplied deployed definition can first be imported and saved as a separate configuration.</p><div class="form-grid"><label>Deployed configuration<select name="baselineProfileId" data-baseline-profile>${options(list(workspace.profiles),ui.baselineProfileId,'No deployed baseline declared')}</select></label>${ui.baselineProfileId?`<label>Deployed saved version<select name="baselineVersionId" data-ui="baselineVersionId" required>${options(versions,ui.baselineVersionId,'Choose exact deployed version')}</select></label><label>Declared by<input name="baselineDeclaredBy" data-ui="baselineDeclaredBy" value="${esc(ui.baselineDeclaredBy??'')}" required></label><label>Deployment reference and notes<textarea name="baselineNote" data-ui="baselineNote" rows="4" required>${esc(ui.baselineNote??'')}</textarea></label>`:''}</div><p class="hint">The handover retains this declaration and its exact profile version. When no baseline is declared, it includes the configuration inputs still needed to prepare migration.</p></details>`;}
async function chooseBaselineProfile(id){ui.baselineProfileId=id;ui.baselineVersionId='';ui.baselineVersions=[];if(id){const d=await api(url('/api/profile',{id}));const versions=[d.profile,...list(d.history)].filter(Boolean);ui.baselineVersions=versions.filter((v,i)=>versions.findIndex(other=>other.versionId===v.versionId)===i);}await render();}
function readBaseline(data){const profileId=String(data.get('baselineProfileId')??'');if(!profileId)return undefined;if(profileId!==ui.baselineProfileId)throw new Error('Wait for the selected deployed configuration history to load.');const profileVersionId=String(data.get('baselineVersionId')??''),declaredBy=String(data.get('baselineDeclaredBy')??'').trim(),note=String(data.get('baselineNote')??'').trim();if(!list(ui.baselineVersions).some(v=>v.versionId===profileVersionId))throw new Error('Choose the exact saved version used by the agency.');if(!declaredBy||!note)throw new Error('Name the person declaring the deployed configuration and its deployment reference.');return{profileId,profileVersionId,declaredBy,note};}

function overview(){const profiles=list(workspace.profiles),sources=list(workspace.sources),previews=list(workspace.previews),releases=list(workspace.releases);return pageHeading('Agency service configuration','Prepare categories, responsibilities, source mappings and resident progress for a complete agency rollout.',button('New configuration','new-profile','',true))+`<div class="cards">${[[profiles.length,'Saved configurations'],[sources.length,'Original source files'],[previews.length,'Routing previews'],[releases.length,'Implementation handovers']].map(([n,l])=>`<div class="card"><span class="number">${count(n)}</span><p>${esc(l)}</p></div>`).join('')}</div><div class="split"><section class="panel"><h2>Configure the service</h2><ol><li>Save agency categories, roles, staff and progress templates.</li><li>Declare original source fields and the exact meaning of each source status.</li><li>Retain the original request file and select its row array.</li><li>Preview every row, resolve ambiguous routing and review deadlines and messages.</li><li>Issue the complete configuration and operating handover.</li></ol></section><section class="panel"><h2>Continue a saved operation</h2><p>The full workspace carries profile versions, original sources, previews and released configurations. Receiving opens the same work in a separate empty workspace.</p><div class="actions">${downloadLink('Download editable workspace','workspace')}${button('Open a handover','view-transfer')}</div></section></div><section class="panel"><h2>Recent handovers</h2>${table(['Handover','Reviewed by','Created',''],releases.slice(-10).reverse().map(r=>[esc(r.name),esc(r.reviewer),esc(stamp(r.createdAt)),button('Open','open-release',`data-id="${esc(r.id)}"`)]))}</section>`;}
async function renderSources(){let panel='';if(ui.sourceId){const[d,p]=await Promise.all([api(url('/api/source',{id:ui.sourceId})),api(url('/api/source-rows',{sourceId:ui.sourceId,offset:ui.sourceOffset,limit:100,q:ui.sourceQuery}))]);detail=d;ui.sourceRows=p.items;panel=`<section class="panel"><div class="section-heading"><div><h2>${esc(d.source.name)}</h2><p class="muted">${count(d.source.rowCount)} original rows · array ${esc(d.source.selection?.rowsPointer||'(root)')}</p></div><div class="actions">${downloadLink('Original file','source',{sourceId:ui.sourceId})}${button('View source metadata','source-metadata')}</div></div><form id="source-search" class="search-row"><label for="source-query">Find original records<input id="source-query" name="q" value="${esc(ui.sourceQuery)}" placeholder="Search source values"></label><button type="submit">Search</button></form>${table(['Original row','Preview of source values',''],list(p.items).map((r,i)=>[`<code>${esc(r.key)}</code><small class="block">${esc(r.pointer)}</small>`,`<pre class="compact">${esc(pretty(r.value).slice(0,550))}${pretty(r.value).length>550?'…':''}</pre>`,button('Open full original','source-row',`data-index="${i}"`)]))}${pager(p,'source-page')}</section>`;}return pageHeading('Original request sources','Retain complete original JSON and explicitly select the array used by a source mapping.')+`<section class="panel"><h2>Receive an original file</h2><form id="source-import"><div class="form-grid two"><label for="source-name">Source name<input id="source-name" name="name" value="${esc(ui.sourceName??'')}" data-ui="sourceName" required></label><label for="source-file">Original JSON file<input id="source-file" type="file" accept=".json,application/json" data-file="source"></label></div>${ui.sourceFilename?`<p class="hint">Loaded ${esc(ui.sourceFilename)}. The complete original body is retained for import.</p>`:''}<label for="source-paste">Or paste complete original JSON<textarea id="source-paste" rows="6" data-ui="sourceText" placeholder="Paste the complete original file">${esc(ui.sourceFilename?'':ui.sourceText)}</textarea></label><div class="actions">${button('Inspect original arrays','inspect-source')}</div>${ui.inspection?`<div class="subpanel"><p>${count(ui.inspection.originalFile.bytes)} bytes · SHA-256 <code>${esc(ui.inspection.originalFile.sha256)}</code></p><label for="source-array">Original row array<select id="source-array" name="rowsPointer" required><option value="">Choose an original array</option>${list(ui.inspection.arrays).map(a=>`<option value="${esc('array:'+a.pointer)}"${ui.sourcePointer===a.pointer?' selected':''}>${esc(a.pointer||'(root array)')} · ${count(a.rows)} rows${a.fields?.length?' · '+esc(a.fields.slice(0,8).join(', ')):''}</option>`).join('')}</select></label><button type="submit" class="primary">Retain selected source</button></div>`:''}</form></section>${table(['Saved source','Original rows','Row array','Saved',''],list(workspace.sources).map(s=>[esc(s.name),count(s.rowCount),`<code>${esc(s.selection?.rowsPointer||'(root)')}</code>`,esc(stamp(s.createdAt)),button('Open source','open-source',`data-id="${esc(s.id)}"`)]))}${panel}`;}
function overrideTable(){return table(['Original source key','Category / responsibility','Progress / map','Reason',''],ui.overrides.map((o,i)=>[`<label for="override-key-${i}">Original key<input id="override-key-${i}" data-override-index="${i}" data-override-field="sourceKey" value="${esc(o.sourceKey??'')}" required></label>`,`<label>Category<select data-override-index="${i}" data-override-field="categoryId">${options(list(ui.previewProfile?.definition.categories),o.categoryId,'Keep calculated category')}</select></label><label>Department<select data-override-index="${i}" data-override-field="departmentId">${options(list(ui.previewProfile?.definition.departments),o.departmentId,'Keep calculated department')}</select></label><label>Owner<select data-override-index="${i}" data-override-field="ownerStaffId">${options(list(ui.previewProfile?.definition.staff),o.ownerStaffId,'Keep calculated owner')}</select></label>`,`<label>Stage<select data-override-index="${i}" data-override-field="stage">${options(['received','assigned','in_progress','resolved','closed_other'],o.stage,'Keep original stage')}</select></label><label>Public map<select data-override-index="${i}" data-override-field="publicMap">${options(['hide','show'],o.publicMap,'Keep calculated setting')}</select></label>`,`<label>Override reason<textarea data-override-index="${i}" data-override-field="reason" rows="3" required>${esc(o.reason??'')}</textarea></label>`,button('Remove','remove-override',`data-index="${i}"`)]),'No explicit overrides. The engine will show unmatched or conflicting source rows for review.');}
async function previewPanel(){if(!ui.previewId)return '';const p=await api(url('/api/preview',{id:ui.previewId,offset:ui.previewOffset,limit:100,q:ui.previewQuery}));ui.previewPage=p;const v=p.preview;let profile=ui.previewDisplayProfile;if(!profile||profile.id!==v.profileId||profile.versionId!==v.profileVersionId){const d=await api(url('/api/profile',{id:v.profileId}));profile=[d.profile,...list(d.history)].find(x=>x.versionId===v.profileVersionId)??null;ui.previewDisplayProfile=profile;}const defs=profile?.definition??{};const nameOf=(kind,id)=>list(defs[kind]).find(x=>x.id===id)?.name??id??'—';return `<section class="panel"><div class="section-heading"><div><h2>${esc(v.name)}</h2><p class="muted">${count(v.rowCount)} source rows · profile version ${esc(short(v.profileVersionId))}</p></div><div class="actions">${downloadLink('Complete preview JSON','preview-json',{previewId:v.id})}${downloadLink('Complete routing CSV','preview-csv',{previewId:v.id})}${button('View saved inputs','preview-inputs')}</div></div><div class="cards">${Object.entries(v.counts??{}).map(([k,n])=>`<div class="card"><span class="number">${count(n)}</span><p>${esc(title(k))}</p></div>`).join('')}</div>${v.implications?.length?`<details class="panel"><summary>Configuration application order</summary><pre>${esc(pretty(v.implications))}</pre></details>`:''}<form id="preview-search" class="search-row"><label>Find routing results<input name="q" value="${esc(ui.previewQuery)}" placeholder="Search request, category or routing"></label><button type="submit">Search</button></form>${table(['Original request','Category / responsibility','Due date / stage','Public map','Review',''],list(p.items).map((r,i)=>[`<strong>${esc(r.serviceRequestId||r.sourceKey)}</strong><small class="block">${esc(r.source?.serviceName??r.source?.category??r.source?.serviceCode??'')}</small><code>${esc(r.sourcePointer)}</code>`,`<strong>${esc(r.category?.name??'Unmatched')}</strong><small class="block">${esc(nameOf('departments',r.routing?.departmentId))}</small><small class="block">${esc(nameOf('staff',r.routing?.ownerStaffId))}</small>`,`${esc(r.due?.date??'—')}<small class="block">${esc(r.due?.timeZone??'')}</small><span class="badge">${esc(title(r.stage??'unmapped'))}</span>`,`${esc(title(r.publicMap?.value??'unresolved'))}<small class="block">${esc(r.publicMap?.basis??'')}</small>`,`<span class="badge">${esc(title(r.state))}</span>${list(r.issues).map(x=>`<small class="block">${esc(x.message)}</small>`).join('')}`,`<div class="actions">${button('Details and messages','preview-row',`data-index="${i}"`)}${button('Prepare override','row-override',`data-index="${i}"`)}</div>`]))}${pager(p,'preview-page')}</section>`;}
async function renderPreviews(){return pageHeading('Routing and progress preview','Calculate the complete original register against one saved configuration version. Review responsibility, date-only deadlines and the exact progress messages.')+`<section class="panel"><h2>Prepare a routing preview</h2><form id="preview-create"><div class="form-grid"><label>Preview name<input name="name" data-ui="previewName" value="${esc(ui.previewName??'')}" required></label><label>Saved configuration<select name="profileId" data-preview-profile required>${options(list(workspace.profiles),ui.previewProfileId,'Choose configuration')}</select></label><label>Original source<select name="sourceId" data-ui="previewSourceId" required>${options(list(workspace.sources),ui.previewSourceId,'Choose source')}</select></label><label>Source field mapping<select name="sourceProfileId" data-ui="previewSourceProfileId" required>${options(list(ui.previewProfile?.definition.sourceProfiles),ui.previewSourceProfileId,'Choose declared mapping')}</select></label></div>${ui.previewProfile?`<p class="hint">Current saved profile ${esc(short(ui.previewProfile.versionId))}. The selected source array must match the declared mapping.</p>`:''}${deployedBaselinePanel()}<details class="panel"${ui.overrides.length?' open':''}><summary>Explicit per-request overrides (${count(ui.overrides.length)})</summary><p>Choose only the fields that this review changes and give the reason. Leave other choices at their calculated values.</p>${overrideTable()}${button('Add request override','add-override')}</details><button type="submit" class="primary">Save complete preview</button></form></section>${table(['Saved preview','Rows','Ready','Needs review','Saved',''],list(workspace.previews).map(p=>[esc(p.name),count(p.rowCount),count(p.counts?.ready),count(Number(p.counts?.unmatched??0)+Number(p.counts?.conflict??0)+Number(p.counts?.invalid??0)),esc(stamp(p.createdAt)),button('Open preview','open-preview',`data-id="${esc(p.id)}"`)]))}${await previewPanel()}`;}
function releaseForm(){return `<section class="panel"><h2>Issue an implementation handover</h2><form id="release-create"><div class="form-grid"><label>Handover name<input name="name" data-ui="releaseName" value="${esc(ui.releaseName??'')}" required></label><label>Reviewed routing preview<select name="previewId" required>${options(list(workspace.previews),ui.releasePreviewId,'Choose saved preview')}</select></label><label>Reviewer<input name="reviewer" data-ui="releaseReviewer" value="${esc(ui.releaseReviewer??'')}" required></label></div><label>Operating handover notes<textarea name="note" data-ui="releaseNote" rows="5">${esc(ui.releaseNote??'')}</textarea></label><p class="hint">The handover binds the reviewed preview to its exact saved profile version. It includes the declared responsibilities, rendered progress messages, source mappings and rollout procedure.</p><button type="submit" class="primary">Issue complete handover</button></form></section>`;}
async function renderReleases(){let panel='';if(ui.releaseId){const d=await api(url('/api/release',{id:ui.releaseId}));ui.releaseDetail=d;const r=d.release??d;panel=`<section class="panel"><div class="section-heading"><div><h2>${esc(r.name)}</h2><p class="muted">Reviewed by ${esc(r.reviewer)} · ${esc(stamp(r.createdAt))}</p></div><div class="actions">${downloadLink('Editable handover JSON','release-json',{releaseId:r.id})}${downloadLink('Operating handover','release-report',{releaseId:r.id})}${button('View complete handover','release-detail')}</div></div><dl class="facts"><dt>Configuration version</dt><dd><code>${esc(r.profileVersionId??r.profile?.versionId??'')}</code></dd><dt>Original routing preview</dt><dd><code>${esc(r.previewId??r.preview?.id??'')}</code></dd><dt>Review notes</dt><dd>${esc(r.note??'')}</dd></dl>${r.implications?.length?`<h3>Application order</h3><pre>${esc(pretty(r.implications))}</pre>`:''}</section>`;}return pageHeading('Implementation handovers','Keep the full configuration, source-backed routing review, staff instructions and rollout together.')+releaseForm()+table(['Handover','Reviewer','Created',''],list(workspace.releases).map(r=>[esc(r.name),esc(r.reviewer),esc(stamp(r.createdAt)),button('Open handover','open-release',`data-id="${esc(r.id)}"`)]))+panel;}
function transfer(){return pageHeading('Open an editable workspace','Receive the original complete workspace into this new empty workspace, then continue its saved profiles and operating history.')+`<section class="panel"><form id="workspace-receive"><label for="workspace-file">Complete service-configuration workspace JSON<input id="workspace-file" name="workspace" type="file" accept=".json,application/json" required></label><button type="submit" class="primary">Receive editable workspace</button></form></section><section class="panel"><h2>Save this workspace</h2><p>Download the complete saved history, including original source bodies and complete routing previews.</p>${downloadLink('Download editable workspace','workspace')}</section>${workspace.receivedFrom?.length?`<details class="panel"><summary>Original receiving history</summary><pre>${esc(pretty(workspace.receivedFrom))}</pre></details>`:''}`;}
async function renderView(view){switch(view){case'profiles':return renderProfiles();case'sources':return renderSources();case'previews':return renderPreviews();case'releases':return renderReleases();case'transfer':return transfer();default:return overview();}}
function showPreviewRow(row){$('#record-title').textContent='Request '+String(row.serviceRequestId||row.sourceKey);$('#record-content').innerHTML=`<h3>Responsibility and date calculation</h3><pre>${esc(pretty({source:row.source,category:row.category,routing:row.routing,due:row.due,publicMap:row.publicMap,stage:row.stage,state:row.state,issues:row.issues}))}</pre><h3>Rendered progress messages</h3>${list(row.templates).length?list(row.templates).map(t=>`<section class="subpanel"><p class="muted">${esc(title(t.audience))} · ${esc(t.id)}</p><h3>${esc(t.subject)}</h3><p class="message-body">${esc(t.body)}</p></section>`).join(''):'<p>No applicable rendered templates.</p>'}<details><summary>Complete original routing result</summary><pre>${esc(pretty(row))}</pre></details>`;$('#record-dialog').showModal();}

async function readOriginalFile(file){if(!file)throw new Error('Choose the complete original file.');if(file.size>256*1024*1024)throw new Error('Choose a complete file of at most 256 MiB.');try{return new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(await file.arrayBuffer());}catch(error){if(error instanceof TypeError)throw new Error('The complete original file must use valid UTF-8. Save it as UTF-8 and choose that complete edition.');throw error;}}

function ensureValidDraft(){const form=$('#profile-form');if(form&&!form.reportValidity())throw new Error('Complete the highlighted configuration fields.');if(Object.keys(ui.rawDrafts).length)throw new Error('Correct the JSON values in the working draft before saving. The draft download preserves the entered values.');}
async function saveProfile(){ensureValidDraft();if(ui.profileId){const latest=await api(url('/api/profile',{id:ui.profileId}));if(latest.profile.versionId!==ui.baseVersion){ui.staleDraft=true;detail=latest;await rememberDraft();await render();throw new Error('A newer profile version was saved. Compare the retained draft with the current profile before saving.');}}const oldKey=storageKey('profile-draft:'+String(ui.profileId||'new'));const result=await write('/api/profiles',{profile:{...(ui.profileId?{id:ui.profileId}:{}),definition:copy(ui.draft)}});await localWrite(oldKey,null);ui.profileId=result.profile.id;await localWrite(storageKey('profile-draft:'+ui.profileId),null);await openProfile(ui.profileId);notice('The complete configuration version is saved.');}
function shiftRawDrafts(path,oldItems,newItems){const prefix=path+'.',next={};for(const[k,v]of Object.entries(ui.rawDrafts)){if(!k.startsWith(prefix)){next[k]=v;continue;}const tail=k.slice(prefix.length),cut=tail.indexOf('.'),index=Number(cut<0?tail:tail.slice(0,cut)),newIndex=newItems.indexOf(oldItems[index]);if(newIndex>=0)next[prefix+newIndex+(cut<0?'':tail.slice(cut))]=v;}ui.rawDrafts=next;}
function readProfileImport(value){const parsed=JSON.parse(value),def=parsed.definition??parsed.profile?.definition??parsed;if(!def||typeof def!=='object'||!def.agency||!Array.isArray(def.categories))throw new Error('Choose a complete service-configuration definition or exported profile. Use Open a handover for a complete workspace.');return copy(def);}
function chooseProfileFile(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.hidden=true;document.body.append(input);input.addEventListener('change',()=>run(async()=>{try{const file=input.files?.[0];if(!file)return;ui.profileId='';ui.baseVersion=null;ui.baseDefinition=null;ui.staleDraft=false;ui.rawDrafts={};const originalText=await readOriginalFile(file),parsed=JSON.parse(originalText);ui.draft=readProfileImport(originalText);ui.rawDrafts=copy(parsed.unparsedFields??{});ui.section='agency';ui.view='profiles';detail=null;await rememberDraft();location.hash='profiles';await render();notice('The complete definition is open as a new editable configuration.');}finally{input.remove();}}),{once:true});input.click();}
async function inspectSource(){if(!ui.sourceText.trim())throw new Error('Choose or paste the complete original JSON first.');const originalText=ui.sourceText,result=await api('/api/source-inspect',{originalText});if(ui.sourceText!==originalText){ui.inspection=null;notice('The original text changed during inspection. Inspect the current complete text.');return;}ui.inspection=result;ui.sourcePointer=undefined;await render();notice('Choose the exact original row array for this source.');}
function renderMessages(row){showPreviewRow(row);}
async function clickAction(el){const action=el.dataset.action;switch(action){
case'dismiss-error':clearError();return;
case'close-dialog':$('#record-dialog').close();return;
case'refresh':if(ui.draft)await rememberDraft();await refreshState();if(ui.profileId&&ui.draft){const d=await api(url('/api/profile',{id:ui.profileId}));detail=d;ui.staleDraft=d.profile.versionId!==ui.baseVersion;}await render();notice('Saved workspace refreshed.');return;
case'check-pending':return recover(false);
case'resume-pending':return recover(true);
case'save-pending':if(pending)saveFile('service-configuration-saved-request.json',pretty(pending)+'\n');return;
case'new-profile':ui.section='agency';return openProfile('');
case'open-profile':return openProfile(el.dataset.id);
case'import-profile':return chooseProfileFile();
case'close-profile':await rememberDraft();ui.draft=null;ui.profileId='';ui.staleDraft=false;detail=null;return render();
case'save-profile':return saveProfile();
case'fork-profile':ui.profileId='';ui.baseVersion=null;ui.baseDefinition=null;ui.staleDraft=false;detail=null;await rememberDraft();return saveProfile();
case'download-draft':if(ui.draft)saveFile('service-configuration-working-definition.json',pretty({schema:'commons.open311.service-configuration-draft.v1',profileId:ui.profileId||null,baseVersion:ui.baseVersion,definition:ui.draft,unparsedFields:ui.rawDrafts})+'\n');return;
case'show-saved-profile':if(detail?.profile)recordDialog('Current saved configuration',detail.profile);return;
case'load-current-profile':await localWrite(storageKey('profile-draft:'+ui.profileId),null);return openProfile(ui.profileId);
case'profile-version':{const v=[detail?.profile,...list(detail?.history)].find(r=>r?.versionId===el.dataset.version);if(v)recordDialog('Saved configuration version',v);return;}
case'profile-section':await rememberDraft();ui.section=el.dataset.section;return render();
case'add-item':{const path=el.dataset.path,items=list(getPath(ui.draft,path));setPath(ui.draft,path,[...items,newItem(el.dataset.kind)]);await rememberDraft();await render();const panels=$$('.profile-section .panel');panels.at(-1)?.scrollIntoView({block:'nearest'});return;}
case'remove-item':{const path=el.dataset.path,old=list(getPath(ui.draft,path)),next=old.filter((_,i)=>i!==Number(el.dataset.index));shiftRawDrafts(path,old,next);setPath(ui.draft,path,next);await rememberDraft();return render();}
case'move-item':{const path=el.dataset.path,old=list(getPath(ui.draft,path)),next=[...old],i=Number(el.dataset.index),j=i+Number(el.dataset.direction);if(j<0||j>=next.length)return;[next[i],next[j]]=[next[j],next[i]];shiftRawDrafts(path,old,next);if(path==='categories')for(let n=0;n<next.length;n++)next[n].displayOrder=n;setPath(ui.draft,path,next);await rememberDraft();return render();}
case'inspect-source':return inspectSource();
case'open-source':ui.sourceId=el.dataset.id;ui.sourceOffset=0;ui.sourceQuery='';return render();
case'source-page':ui.sourceOffset=Number(el.dataset.offset);return render();
case'source-metadata':recordDialog('Original source metadata',detail?.source);return;
case'source-row':recordDialog('Complete original source row',ui.sourceRows?.[Number(el.dataset.index)]);return;
case'open-preview':ui.previewId=el.dataset.id;ui.previewOffset=0;ui.previewQuery='';return render();
case'preview-page':ui.previewOffset=Number(el.dataset.offset);return render();
case'preview-inputs':recordDialog('Saved routing preview',ui.previewPage?.preview);return;
case'preview-row':return renderMessages(ui.previewPage.items[Number(el.dataset.index)]);
case'row-override':{const r=ui.previewPage.items[Number(el.dataset.index)],p=ui.previewPage.preview;ui.previewProfileId=p.profileId;ui.previewProfile=(await api(url('/api/profile',{id:p.profileId}))).profile;ui.previewSourceId=p.sourceId;ui.previewSourceProfileId=p.sourceProfileId;if(!ui.overrides.some(o=>o.sourceKey===r.sourceKey))ui.overrides.push({sourceKey:r.sourceKey,reason:''});await render();$('#preview-create')?.scrollIntoView({block:'start'});return;}
case'add-override':ui.overrides.push({sourceKey:'',reason:''});return render();
case'remove-override':ui.overrides.splice(Number(el.dataset.index),1);return render();
case'open-release':ui.releaseId=el.dataset.id;return render();
case'release-detail':recordDialog('Complete implementation handover',ui.releaseDetail?.release??ui.releaseDetail);return;
case'view-transfer':location.hash='transfer';return navigate('transfer');
default:return;
}}
async function submitForm(form){const data=new FormData(form);switch(form.id){
case'profile-form':return saveProfile();
case'source-search':ui.sourceQuery=String(data.get('q')??'');ui.sourceOffset=0;return render();
case'preview-search':ui.previewQuery=String(data.get('q')??'');ui.previewOffset=0;return render();
case'source-import':{const selected=String(data.get('rowsPointer')??'');if(!ui.inspection||!selected.startsWith('array:'))throw new Error('Inspect the original file and choose its row array first.');const result=await write('/api/sources',{name:String(data.get('name')??'').trim(),originalText:ui.sourceText,selection:{rowsPointer:selected.slice(6)}});ui.sourceId=result.source.id;ui.sourceOffset=0;ui.sourceQuery='';ui.sourceText='';ui.sourceFilename='';ui.inspection=null;await render();notice('The complete original file and selected array are saved.');return;}
case'preview-create':{if(!ui.previewProfile)throw new Error('Choose a saved configuration first.');const profileId=String(data.get('profileId')??'');if(profileId!==ui.previewProfile.id)throw new Error('Wait for the selected configuration to load.');const overrides=ui.overrides.map(o=>Object.fromEntries(Object.entries(o).filter(([k,v])=>k==='sourceKey'||k==='reason'||v!==''&&v!==undefined)));const result=await write('/api/previews',{name:String(data.get('name')??'').trim(),profileId,expectedProfileVersionId:ui.previewProfile.versionId,sourceId:String(data.get('sourceId')??''),mapping:{sourceProfileId:String(data.get('sourceProfileId')??'')},overrides,...(readBaseline(data)?{baseline:readBaseline(data)}:{})});ui.previewId=result.preview.id;ui.previewOffset=0;ui.previewQuery='';await render();notice('The complete routing preview is saved with its original source and configuration version.');return;}
case'release-create':{const previewId=String(data.get('previewId')??'');const selected=list(workspace.previews).find(p=>p.id===previewId);if(!selected)throw new Error('Choose the saved routing preview for this handover.');const result=await write('/api/releases',{name:String(data.get('name')??'').trim(),profileId:selected.profileId,expectedProfileVersionId:selected.profileVersionId,previewId,reviewer:String(data.get('reviewer')??'').trim(),note:String(data.get('note')??'')});ui.releaseId=result.release.id;await render();notice('The complete implementation handover is saved.');return;}
case'workspace-receive':{const file=form.elements.workspace.files?.[0];if(!file)throw new Error('Choose the complete editable workspace JSON.');const result=await write('/api/receive',{originalText:await readOriginalFile(file)});ui.draft=null;ui.profileId='';ui.previewId='';ui.releaseId='';ui.sourceId='';await refreshState();await render();notice('The original editable workspace is received and ready to continue.');return;}
}}
function mappingInput(el){const index=Number(el.dataset.profileIndex),name=el.dataset.mapValue,profile=ui.draft.sourceProfiles[index],entry=profile.mapping[name],path='sourceProfiles.'+index+'.mapping.'+name;if(entry&&Object.prototype.hasOwnProperty.call(entry,'literal')){try{entry.literal=JSON.parse(el.value);delete ui.rawDrafts[path];el.setCustomValidity('');}catch{ui.rawDrafts[path]=el.value;el.setCustomValidity('Enter a JSON literal.');}}else if(entry)entry.pointer=el.value;queueDraft();}
function prepareListeners(){
document.addEventListener('click',event=>{const nav=event.target.closest('[data-view]');if(nav){event.preventDefault();if(busy){ui.queuedView=nav.dataset.view;return;}location.hash=nav.dataset.view;run(()=>navigate(nav.dataset.view));return;}const action=event.target.closest('[data-action]');if(action){event.preventDefault();if(action.dataset.action==='dismiss-error'||action.dataset.action==='close-dialog'){clickAction(action).catch(showError);return;}run(()=>clickAction(action));}});
document.addEventListener('submit',event=>{if(!(event.target instanceof HTMLFormElement))return;event.preventDefault();run(()=>submitForm(event.target));});
document.addEventListener('input',event=>{const el=event.target;if(el.dataset.path)inputDraft(el);if(el.dataset.ui){ui[el.dataset.ui]=el.value;if(el.dataset.ui==='sourceText'){ui.inspection=null;ui.sourceFilename='';}}if(el.dataset.mapValue)mappingInput(el);if(el.dataset.overrideField){const o=ui.overrides[Number(el.dataset.overrideIndex)];if(o)o[el.dataset.overrideField]=el.value;}});
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.path)inputDraft(el);if(el.dataset.ui)ui[el.dataset.ui]=el.value;if(el.dataset.baselineProfile!==undefined)run(()=>chooseBaselineProfile(el.value));if(el.dataset.previewProfile!==undefined)run(async()=>{ui.previewProfileId=el.value;ui.previewProfile=el.value?(await api(url('/api/profile',{id:el.value}))).profile:null;ui.previewSourceProfileId='';await render();});if(el.dataset.mapKind)run(async()=>{const profile=ui.draft.sourceProfiles[Number(el.dataset.profileIndex)],name=el.dataset.mapKind,path='sourceProfiles.'+el.dataset.profileIndex+'.mapping.'+name;delete ui.rawDrafts[path];if(el.value==='unused')delete profile.mapping[name];else profile.mapping[name]=el.value==='literal'?{literal:null}:{pointer:''};await rememberDraft();await render();});if(el.dataset.file==='source')run(async()=>{const file=el.files?.[0];if(!file)return;if(file.size>256*1024*1024)throw new Error('Choose a complete original JSON file of at most 256 MiB.');ui.sourceText=await readOriginalFile(file);ui.sourceFilename=file.name;ui.inspection=null;await render();notice('Original file loaded. Inspect it to choose the correct row array.');});if(el.dataset.overrideField){const o=ui.overrides[Number(el.dataset.overrideIndex)];if(o)o[el.dataset.overrideField]=el.value;}if(el.id==='source-array')ui.sourcePointer=el.value.startsWith('array:')?el.value.slice(6):undefined;});
window.addEventListener('hashchange',()=>{if(busy)return;run(()=>navigate(location.hash.slice(1)));});
window.addEventListener('beforeunload',event=>{if(ui.draft){try{localStorage.setItem(storageKey('profile-draft:'+String(ui.profileId||'new')),JSON.stringify({savedAt:Date.now(),value:{profileId:ui.profileId,definition:ui.draft,baseVersion:ui.baseVersion,baseDefinition:ui.baseDefinition,rawDrafts:ui.rawDrafts,savedAt:new Date().toISOString()}}));}catch{event.preventDefault();event.returnValue='';}}});
}
async function start(){prepareListeners();await refreshState();pending=await localRead(storageKey('pending'));ui.view=views.includes(location.hash.slice(1))?location.hash.slice(1):'overview';await render();header();}
start().catch(showError);

})();

