const SETUP = 'stellar-forge.open311-service-configuration-native-setup.v1';
const need = (value, message) => { if (!value) throw failure('OPEN311_SERVICE_CONFIGURATION_SETUP_CONFLICT', message); };
async function optional(path, maximum = 1024 * 1024) {
  try { return await readPrivateJson(path, maximum); }
  catch (error) { if (error.code === 'ENOENT') return null; throw error; }
}
async function directorySync(path) {
  const handle = await open(path, 'r');
  try { await handle.sync(); } finally { await handle.close(); }
